create temporary table currency_payout_checks(label text primary key);
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();p uuid:=gen_random_uuid();item uuid;o uuid;one uuid;two uuid;pay1 uuid;pay2 uuid;r1 uuid;r2 uuid;r jsonb;body jsonb;failed boolean;d date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date-1;
begin
 insert into auth.users(id,email) values(a,'qa-usd-admin-'||a||'@example.invalid'),(u,'qa-usd-one-'||u||'@example.invalid'),(v,'qa-usd-two-'||v||'@example.invalid');
 insert into public.profiles(id,email,role,status,permissions) values(a,'qa-usd-admin-'||a||'@example.invalid','super_admin','active','{}'),(u,'qa-usd-one-'||u||'@example.invalid','viewer','active','{}'),(v,'qa-usd-two-'||v||'@example.invalid','viewer','active','{}');
 insert into public.sales_products(id,sku,name,unit_price_vnd,status,product_group) values(p,'QA-USD-'||p,'QA USD',100000,'active','fanpage');
 r:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','990019232001','page_name','QA USD Page','page_link','https://facebook.com/990019232001'));item:=(r->'item'->>'id')::uuid;
 perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',item));r:=public.sales_inventory_command('create_inhouse_order',a,jsonb_build_object('product_id',p,'buyer_user_id',u,'quantity',1));o:=(r->>'order_id')::uuid;
 perform public.sales_inventory_command('reserve',a,jsonb_build_object('order_id',o,'destination','inhouse','inventory_item_ids',jsonb_build_array(item)));perform public.sales_inventory_command('verify_zero',a,jsonb_build_object('order_id',o));perform public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',o));
 r:=public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',item,'user_id',u));one:=(r->>'assignment_id')::uuid;r:=public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',item,'user_id',v));two:=(r->>'assignment_id')::uuid;
 update public.page_assignments set assigned_at=now()-interval '3 days' where id in(one,two);
 body:=jsonb_build_object('assignment_id',one,'report_date',d,'published_post_count',3,'currency','USD','revenue_amount',12.34,'cumulative_amount',23.45);
 failed:=false;begin perform public.content_report_command('submit',u,body);exception when raise_exception then if sqlerrm='Page payout required' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA missing payout allowed';end if;insert into currency_payout_checks values('missing payout blocks new report');
 failed:=false;begin perform public.inhouse_payout_save(u,jsonb_build_object('page_id','990019232001','external_id','QA forbidden'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA unauthorized payout';end if;insert into currency_payout_checks values('payout permission required');
 r:=public.inhouse_payout_save(a,jsonb_build_object('page_id','990019232001','external_id','QA-USD1-'||p,'profile_name','QA USD payout','currency','USD'));pay1:=(r->>'payment_profile_id')::uuid;
 perform public.inhouse_payout_save(a,jsonb_build_object('page_id','990019232001','payment_profile_id',pay1));if (select count(*) from public.page_payout_assignment_history where page_id='990019232001')<>1 then raise exception 'QA payout retry duplicated history';end if;insert into currency_payout_checks values('profile created and attached idempotently');
 r:=public.content_report_command('submit',u,body);r1:=(r->'report'->>'id')::uuid;
 if not exists(select 1 from public.content_assignment_daily_reports where id=r1 and currency='USD' and revenue_amount=12.34 and cumulative_amount=23.45 and revenue_vnd=0 and cumulative_revenue_vnd=0 and payment_profile_id=pay1) then raise exception 'QA USD stored in wrong unit';end if;insert into currency_payout_checks values('USD amounts and payout snapshot without VND mixing');
 r:=public.content_report_command('submit',v,body||jsonb_build_object('assignment_id',two,'revenue_amount',1.11));r2:=(r->'report'->>'id')::uuid;if (select sum(revenue_amount) from public.content_assignment_daily_reports where page_id='990019232001')<>13.45 then raise exception 'QA independent rows';end if;insert into currency_payout_checks values('two reporters remain independent on one Page');
 failed:=false;begin perform public.content_report_command('submit',v,body);exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA foreign assignment allowed';end if;insert into currency_payout_checks values('foreign reporter denied');
 failed:=false;begin perform public.content_report_command('submit',u,body||'{"currency":"VND","revenue_vnd":100,"cumulative_revenue_vnd":200}');exception when raise_exception then if sqlerrm='Invalid report currency change' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA currency changed';end if;insert into currency_payout_checks values('existing report currency cannot change');
 failed:=false;begin perform public.content_report_command('submit',u,body||'{"revenue_amount":"NaN"}');exception when raise_exception then if sqlerrm='Invalid report numbers' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA NaN accepted';end if;insert into currency_payout_checks values('nonfinite amounts rejected');
 r:=public.inhouse_payout_save(a,jsonb_build_object('page_id','990019232001','external_id','QA-USD2-'||p,'currency','USD'));pay2:=(r->>'payment_profile_id')::uuid;
 if (select count(*) from public.page_payout_assignments where page_id='990019232001')<>1 or not exists(select 1 from public.page_payout_assignments where page_id='990019232001' and payment_profile_id=pay2) or (select count(*) from public.page_payout_assignment_history where page_id='990019232001')<>2 or (select count(*) from public.page_payment_profiles where page_id='990019232001')<>2 then raise exception 'QA payout replacement lost history';end if;insert into currency_payout_checks values('one current payout with preserved replacement history');
 perform public.content_report_command('submit',u,body||'{"revenue_amount":15.55}');if (select payment_profile_id from public.content_assignment_daily_reports where id=r1)<>pay1 then raise exception 'QA historical payout rewritten';end if;insert into currency_payout_checks values('editing numbers preserves original payout snapshot');
 r:=public.content_report_command('submit',u,body||jsonb_build_object('report_date',d+1));if (r->'report'->>'payment_profile_id')::uuid<>pay2 then raise exception 'QA new report payout';end if;insert into currency_payout_checks values('new day snapshots current payout');
 perform public.content_report_command('verify',a,jsonb_build_object('report_id',r1));failed:=false;begin perform public.content_report_command('submit',u,body);exception when raise_exception then if sqlerrm='Verified report is locked' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA verified edited';end if;insert into currency_payout_checks values('verified report locked');
 if not exists(select 1 from public.content_report_revisions where report_id=r1 and new_data->>'currency'='USD' and new_data->>'payment_profile_id'=pay1::text) then raise exception 'QA revisions lack currency snapshot';end if;insert into currency_payout_checks values('revisions retain currency and payout');
 perform public.inhouse_payout_save(a,jsonb_build_object('page_id','990019232001','external_id','QA-VND-'||p,'currency','VND'));failed:=false;begin perform public.content_report_command('submit',v,body||jsonb_build_object('assignment_id',two,'report_date',d+1));exception when raise_exception then if sqlerrm='USD payout required' then failed:=true;else raise;end if;end;if not failed then raise exception 'QA wrong payout currency';end if;insert into currency_payout_checks values('USD report requires active USD payout');
 if has_table_privilege('authenticated','public.page_payout_assignments','select') or has_function_privilege('authenticated','public.content_report_command(text,uuid,jsonb)','execute') or not (select relrowsecurity from pg_class where oid='public.page_payout_assignments'::regclass) then raise exception 'QA direct client access';end if;insert into currency_payout_checks values('client access denied and RLS enabled');
end $$;
select label as passed from currency_payout_checks order by label;
